import {works,tiers,baseline,money,dateLabel,getWork,quote} from './data.js';
import {purchases,purchase,reset,storageAvailable} from './store.js';
const main=document.querySelector('#main');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>{const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',file:'<path d="M6 3h9l4 4v14H6Z M14 3v5h5 M9 12h7 M9 16h5"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-8"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>'};return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`;};
const link=(href,label,style='')=>`<a href="${href}" class="button ${style}">${label}</a>`;
const art=(w,cls='')=>`<img class="${cls}" src="assets/${w.image}" alt="${esc(w.title)} — ilustrasi contoh ${esc(w.category.toLowerCase())}" loading="lazy" width="1024" height="1024">`;
const orbit=(cls='')=>`<img class="orbit ${cls}" src="assets/orbit.png" alt="Orbit, maskot O pixel OTENTIK" width="1024" height="1024">`;
const badge='<span class="badge">Contoh karya</span>';
const back=(href,label)=>`<a class="back-link" href="${href}">${icon('back')}${label}</a>`;
const demoNote=()=>`<div class="notice">${icon('file')}<p><strong>Ruang simulasi.</strong> Karya dan profil kreator adalah contoh. Harga serta ketentuan belum menjadi penawaran atau kontrak nyata.</p></div>`;
let toastTimer;
function toast(text){const t=document.querySelector('#toast');clearTimeout(toastTimer);t.textContent=text;t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,5000);}
function card(w){return `<article class="art-card"><a href="#/karya/${w.id}" class="art-link" aria-label="Lihat ${w.title}"><div class="art-image" style="background:${w.color}">${art(w)}<span class="art-category">${w.category}</span><span class="art-open">${icon('arrow')}</span></div><div class="art-info"><div class="creator"><span class="avatar">${w.creator[0]}</span>${w.creator} <span>· ${w.city}</span></div><h3>${w.title}</h3><div class="card-bottom"><span>Mulai <strong>${money(w.prices.personal)}</strong></span><span class="tiny">Contoh karya</span></div></div></a></article>`;}
function searchForm(q='',home=false){return `<form id="search-form" class="search">${icon('search')}<label for="search" class="sr-only">Cari karya lokal</label><input type="search" id="search" name="q" value="${esc(q)}" placeholder="Cari motif, ilustrasi, atau kebutuhan brandmu…" autocomplete="off"><button class="button" type="submit">${home?'Temukan karya':'Cari'}</button></form>`;}
function bindHomeSearch(){document.querySelector('#search-form')?.addEventListener('submit',e=>{e.preventDefault();location.hash='/katalog?q='+encodeURIComponent(document.querySelector('#search').value.trim());});}
function home(){main.innerHTML=`<div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">Rumah bagi kreativitas lokal</div><h1>Karya lokal.<br>Cerita baru.<br><span>Potensi tanpa batas.</span></h1><p>Temukan karya yang bikin brand kamu berbeda. Pilih lisensinya, dan ikut tumbuhkan peluang bagi kreatornya.</p><div class="actions">${link('#/katalog','Jelajahi karya '+icon('arrow'))}${link('#/studio','Saya kreator','secondary')}</div><div class="hero-note"><span class="mini-avatars"><b>N</b><b>D</b><b>A</b></span><span><strong>Berawal dari karya. Bertumbuh bersama.</strong><br>Kenali kreator lewat koleksi contoh kami.</span></div></div><div class="hero-collage"><div class="collage-label"><span class="pixel-dot"></span> DARI KREATIVITAS, JADI IDENTITAS</div><a class="collage-main" href="#/karya/rona-tropis">${art(works[0])}<div class="collage-caption"><span>Motif pilihan <strong>Rona Tropis</strong></span><span class="round-arrow">↗</span></div></a><a class="collage-small" href="#/karya/ruang-warna" aria-label="Lihat Ruang Warna">${art(works[1])}</a><div class="royalty-note">${icon('chart')}<span><strong>80% untuk kreator</strong><small>Pembagian royalti simulasi</small></span></div><div class="orbit-peek">${orbit()}<span>Halo, ide baru!</span></div></div></section><div class="trust-strip"><div class="trust-item"><div class="trust-icon">${icon('spark')}</div><div><h3>Kenali cerita karyanya</h3><p>Temukan kreator di balik karya.</p></div></div><div class="trust-item"><div class="trust-icon">${icon('file')}</div><div><h3>Pilih skala penggunaan</h3><p>Lisensi yang mengikuti kebutuhanmu.</p></div></div><div class="trust-item"><div class="trust-icon">${icon('chart')}</div><div><h3>Lihat pembagian nilainya</h3><p>Royalti kreator ditampilkan terbuka.</p></div></div></div><section class="section"><div class="section-head"><div><div class="eyebrow">Koleksi pilihan</div><h2>Temukan klik kreatifmu.</h2><p>Karya dengan karakter, untuk ide yang punya arah.</p></div>${link('#/katalog','Lihat semua '+icon('arrow'),'text')}</div><div class="home-search">${searchForm('',true)}</div><div class="art-grid">${works.map(card).join('')}</div></section><section class="how-block"><div class="how-intro"><span class="eyebrow">Sesederhana itu</span><h2>Dari inspirasi<br>jadi kolaborasi.</h2><p>Hak cipta tetap di kreator.<br>Kamu memilih hak penggunaannya.</p></div><div class="steps"><div><span>01</span><h3>Temukan karyamu</h3><p>Jelajahi motif dan ilustrasi yang cocok dengan cerita brand.</p></div><div><span>02</span><h3>Pilih lisensinya</h3><p>Tentukan skala penggunaan dan lihat pembagian nilainya.</p></div><div><span>03</span><h3>Tumbuh bersama</h3><p>Coba transaksi demo dan lihat royalti tercatat di studio.</p></div></div></section><section class="creator-banner"><div>${orbit()}</div><div><h2>Karyamu punya masa depan.</h2><p>Kenali bagaimana lisensi bisa membuka peluang pendapatan kreator.</p></div>${link('#/studio','Lihat studio demo '+icon('arrow'),'secondary')}</section></div>`;bindHomeSearch();}
function catalog(params){let q=params.get('q')||'',category=params.get('kategori')||'Semua';if(!['Semua','Motif','Ilustrasi'].includes(category))category='Semua';main.innerHTML=`<div class="container page"><div class="page-heading"><div class="eyebrow">Jelajahi karya</div><h1>Ide bagus dimulai<br>dari <span>karya yang tepat.</span></h1><p>Temukan warna, bentuk, dan cerita untuk kebutuhanmu.</p></div>${searchForm(q)}<div class="catalog-toolbar"><div class="filters" role="group" aria-label="Filter kategori">${['Semua','Motif','Ilustrasi'].map(c=>`<button class="chip ${c===category?'selected':''}" data-category="${c}" aria-pressed="${c===category}">${c==='Semua'?'Semua karya':c}</button>`).join('')}</div><p class="muted" id="result-count" role="status"></p></div><div id="results"></div><p class="footnote">Seluruh karya dan profil pada katalog ini merupakan contoh untuk demonstrasi.</p></div>`;
 const update=()=>{const filtered=works.filter(w=>(category==='Semua'||w.category===category)&&`${w.title} ${w.creator} ${w.city} ${w.category} ${w.tags}`.toLowerCase().includes(q.trim().toLowerCase()));document.querySelector('#result-count').textContent=`${filtered.length} karya contoh`;document.querySelector('#results').innerHTML=filtered.length?`<div class="art-grid">${filtered.map(card).join('')}</div>`:`<div class="empty">${orbit()}<h2>Belum menemukan yang pas?</h2><p>Tidak ada karya untuk “${esc(q)}” dalam kategori ini.<br>Coba kata lain atau tampilkan semua karya.</p><button id="reset-filter" class="button secondary">Reset filter</button></div>`;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('selected',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category));});document.querySelector('#reset-filter')?.addEventListener('click',()=>{q='';category='Semua';document.querySelector('#search').value='';update();document.querySelector('#search').focus();});const next=new URLSearchParams();if(q)next.set('q',q);if(category!=='Semua')next.set('kategori',category);history.replaceState(null,'',`#/katalog${next.size?'?'+next:''}`);};
 document.querySelector('#search').addEventListener('input',e=>{q=e.target.value;update();});document.querySelector('#search-form').addEventListener('submit',e=>{e.preventDefault();q=document.querySelector('#search').value;update();});document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;update();}));update();}
function splitBox(q){return `<div class="split"><div><span>Untuk kreator <b>80%</b></span><strong>${money(q.creator)}</strong></div><div><span>Platform <b>20%</b></span><strong>${money(q.platform)}</strong></div><div class="split-track"><span></span></div></div>`;}
function detail(id,params){const w=getWork(id);if(!w)return notFound();let tier=Object.hasOwn(tiers,params.get('tier'))?params.get('tier'):'umkm';main.innerHTML=`<div class="container page">${back('#/katalog','Kembali ke katalog')}<div class="detail-layout"><section><div class="detail-art">${art(w)}${badge}</div><div class="work-story"><div class="eyebrow">Di balik karya</div><h2>Setiap bentuk punya cerita.</h2><p>${w.description}</p><div class="creator-profile"><span class="avatar big">${w.creator[0]}</span><div><strong>${w.creator}</strong><p>Kreator contoh · ${w.city}</p></div></div><div class="meta-row"><span>Kategori<strong>${w.category}</strong></span><span>Pratinjau<strong>Ilustrasi digital</strong></span><span>Kepemilikan<strong>Tetap di kreator</strong></span></div></div></section><section class="license-panel"><span class="overline">${w.category} / Koleksi contoh</span><h1>${w.title}</h1><p class="muted">oleh ${w.creator} · ${w.city}</p><fieldset class="tier-options"><legend>Pilih skala penggunaanmu</legend>${Object.entries(tiers).map(([key,t])=>`<label class="tier-option"><input type="radio" name="tier" value="${key}" ${key===tier?'checked':''}><span><strong>${t.name}</strong><small>${t.short}</small></span><b>${money(w.prices[key])}</b></label>`).join('')}</fieldset><div id="tier-summary"></div><p class="fineprint">Ketentuan dan harga di atas adalah contoh. Pemeriksaan orisinalitas dan kontrak nyata belum tersedia pada demo.</p></section></div></div>`;
 const update=()=>{const q=quote(id,tier);document.querySelector('#tier-summary').innerHTML=`<div class="terms"><h3>Contoh cakupan ${tiers[tier].name}</h3><ul>${tiers[tier].rules.map(r=>`<li>${icon('check')}${r}</li>`).join('')}</ul><p>Tidak termasuk penjualan ulang file sumber atau pengalihan hak cipta.</p></div><div class="price-row"><span>Total lisensi simulasi</span><strong>${money(q.total)}</strong></div>${splitBox(q)}${link(`#/checkout/${id}?tier=${tier}`,'Lanjut ke simulasi '+icon('arrow'),'full')}`;};document.querySelectorAll('[name=tier]').forEach(r=>r.addEventListener('change',()=>{tier=r.value;update();}));update();}
function checkout(id,params){const w=getWork(id),tier=params.get('tier');if(!w||!Object.hasOwn(tiers,tier))return notFound();const q=quote(id,tier);main.innerHTML=`<div class="container page checkout-page">${back(`#/karya/${id}?tier=${tier}`,'Kembali ke pilihan lisensi')}<div class="page-heading"><div class="eyebrow">Langkah terakhir</div><h1>Ide siap.<br><span>Lisensi sesuai.</span></h1><p>Tinjau pilihanmu sebelum mencoba transaksi.</p></div><div class="checkout-layout"><section><div class="checkout-work">${art(w)}<div><span class="overline">${w.category} · Contoh karya</span><h2>${w.title}</h2><p>oleh ${w.creator}</p><span class="tag">Lisensi ${tiers[tier].name}</span></div></div><div class="panel"><h3>Yang termasuk dalam pilihanmu</h3><ul class="check-list">${tiers[tier].rules.map(r=>`<li>${icon('check')}${r}</li>`).join('')}</ul><p class="muted">Hak cipta tetap milik kreator. Dokumen yang muncul setelah konfirmasi hanya ringkasan simulasi.</p></div>${demoNote()}</section><aside class="panel checkout-total"><h2>Ringkasan simulasi</h2><div class="line-item"><span>Lisensi ${tiers[tier].name}</span><strong>${money(q.total)}</strong></div><div class="line-item"><span>Biaya tambahan demo</span><strong>${money(0)}</strong></div><div class="price-row"><span>Total</span><strong>${money(q.total)}</strong></div>${splitBox(q)}<form id="checkout-form"><label class="consent"><input type="checkbox" required id="consent"><span>Saya memahami ini simulasi. Tidak ada pembayaran, unduhan aset berlisensi, atau kontrak nyata.</span></label><button class="button full" type="submit">Konfirmasi simulasi ${icon('arrow')}</button></form><p class="fineprint">Tersimpan hanya di browser ini. Tidak perlu rekening atau kartu pembayaran.</p></aside></div></div>`;document.querySelector('#checkout-form').addEventListener('submit',e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;const p=purchase(id,tier);location.hash='/lisensi/'+p.id;toast(storageAvailable?'Simulasi tercatat. Royalti di studio ikut diperbarui.':'Simulasi tercatat untuk sesi ini; penyimpanan browser tidak tersedia.');});}
function licenses(){const all=purchases();main.innerHTML=`<div class="container page"><div class="section-head"><div class="page-heading"><div class="eyebrow">Ruang penggunaanmu</div><h1>Lisensi saya<span>.</span></h1><p>Semua pilihan karyamu, dalam satu tempat.</p></div>${link('#/katalog','Cari karya lagi '+icon('arrow'),'secondary')}</div>${all.length?`<div class="license-list">${all.map(p=>{const w=getWork(p.workId);return `<article class="license-row">${art(w)}<div><span class="tag">Simulasi · ${tiers[p.tier].name}</span><h3>${w.title}</h3><p>${w.creator} · ${dateLabel(p.date)}</p></div><strong>${money(p.amount)}</strong>${link('#/lisensi/'+p.id,'Lihat ringkasan','secondary small')}</article>`;}).join('')}</div>`:`<div class="empty">${orbit()}<h2>Cerita pertamamu menanti.</h2><p>Belum ada lisensi simulasi. Temukan karya,<br>pilih penggunaan, lalu coba alur lisensinya.</p>${link('#/katalog','Jelajahi karya '+icon('arrow'))}</div>`}<p class="footnote">${storageAvailable?'Data lisensi tersimpan hanya pada browser ini.':'Penyimpanan browser tidak tersedia; data hanya bertahan dalam sesi ini.'} Semua dokumen merupakan simulasi.</p></div>`;}
function license(id){const p=purchases().find(x=>x.id===id);if(!p)return notFound();const w=getWork(p.workId),q=quote(p.workId,p.tier);main.innerHTML=`<div class="container page certificate-page">${back('#/lisensi','Semua lisensi saya')}<div class="success-heading">${orbit()}<div><span class="tag">Transaksi simulasi tercatat</span><h1>Karya bertemu<br><span>peluang baru.</span></h1><p>Ringkasanmu siap. Royalti contoh sudah tercatat di studio.</p></div></div><section class="certificate"><div class="certificate-top"><img src="assets/logo.svg" alt="OTENTIK" width="145" height="36"><span class="tag">DEMO • BUKAN KONTRAK</span></div><h2>Ringkasan lisensi ${tiers[p.tier].name}</h2><p class="record-id">${esc(p.id)}</p><div class="certificate-work">${art(w)}<div><h3>${w.title}</h3><p>${w.creator} · ${w.category}</p><strong>${money(q.total)}</strong></div></div><dl><div><dt>Pemegang contoh</dt><dd>Pembeli demo</dd></div><div><dt>Tanggal simulasi</dt><dd>${dateLabel(p.date)}</dd></div><div><dt>Jenis penggunaan</dt><dd>${tiers[p.tier].name}</dd></div><div><dt>Kepemilikan karya</dt><dd>Tetap di kreator</dd></div></dl><ul class="check-list">${tiers[p.tier].rules.map(r=>`<li>${icon('check')}${r}</li>`).join('')}</ul>${splitBox(q)}<p class="fineprint">Dokumen ini tidak memberikan hak penggunaan nyata, bukan bukti pembayaran, dan tidak dapat digunakan sebagai kontrak lisensi.</p></section><div class="actions center">${link('#/studio','Lihat royalti di studio '+icon('arrow'))}${link('#/katalog','Temukan karya lain','secondary')}</div></div>`;}
function studio(){const newItems=purchases(),all=[...newItems,...baseline].sort((a,b)=>new Date(b.date)-new Date(a.date));const gross=all.reduce((s,p)=>s+p.amount,0),royalties=all.reduce((s,p)=>s+Math.round(p.amount*.8),0);main.innerHTML=`<div class="container page"><div class="section-head"><div class="page-heading"><div class="eyebrow">Studio kreator / Demo bersama</div><h1>Karya berjalan.<br><span>Nilai bertumbuh.</span></h1><p>Ringkasan seluruh kreator contoh. Setiap simulasi baru ikut tercatat.</p></div><button id="reset-demo" class="button secondary">Reset demo</button></div><div class="stats"><div class="stat primary"><span>Total royalti kreator</span><strong id="royalty-total">${money(royalties)}</strong><small>80% dari nilai transaksi simulasi</small></div><div class="stat"><span>Nilai lisensi</span><strong>${money(gross)}</strong><small>${all.length} transaksi contoh dan simulasi</small></div><div class="stat"><span>Karya di katalog</span><strong>${works.length.toString().padStart(2,'0')}</strong><small>${newItems.length} simulasi baru dari browser ini</small></div></div><div class="studio-grid"><section><div class="section-head"><h2>Riwayat royalti</h2><span class="tag">Data demo</span></div><div class="table-wrap"><table><caption class="sr-only">Riwayat transaksi dan royalti kreator</caption><thead><tr><th>Karya / Kreator</th><th>Lisensi</th><th>Royalti 80%</th><th>Tanggal</th></tr></thead><tbody>${all.map(p=>{const w=getWork(p.workId);return `<tr><td>${p.seed?`<strong>${w.title}</strong>`:`<a href="#/lisensi/${p.id}"><strong>${w.title} ↗</strong></a>`}<small>${w.creator} · ${p.seed?'Contoh awal':'Simulasi baru'}</small></td><td>${tiers[p.tier].name}</td><td><strong>${money(Math.round(p.amount*.8))}</strong></td><td>${dateLabel(p.date)}</td></tr>`;}).join('')}</tbody></table></div></section><aside class="orbit-tip">${orbit()}<h3>Nilai yang terbuka.</h3><p>Dari setiap simulasi, 80% dicatat untuk kreator dan 20% untuk platform. Belum ada dana yang dipindahkan.</p><div class="mini-split"><span>Kreator <b>80%</b></span><span>Platform <b>20%</b></span></div></aside></div><section class="section"><div class="section-head"><div><h2>Karya di studio</h2><p>Profil, karya, dan riwayat berikut adalah contoh demonstrasi.</p></div></div><div class="art-grid">${works.map(card).join('')}</div></section><p class="footnote">Reset menghapus transaksi yang kamu buat dan mengembalikan ringkasan ke tiga transaksi contoh awal. Tidak ada saldo yang dapat dicairkan.</p></div>`;document.querySelector('#reset-demo').addEventListener('click',()=>document.querySelector('#reset-dialog').showModal());}
function notFound(){main.innerHTML=`<div class="container page empty">${orbit()}<h1>Halaman tidak ditemukan.</h1><p>Karya atau lisensi ini belum tersedia pada demo.</p>${link('#/katalog','Kembali ke katalog')}</div>`;}
function render(focus=true){const [path,query='']=(location.hash.slice(1)||'/').split('?');const parts=path.split('/').filter(Boolean),params=new URLSearchParams(query);document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(parts[0]||'home');a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.querySelector('#license-count').textContent=purchases().length;document.title=`${({'katalog':'Jelajahi karya','karya':'Detail karya','checkout':'Simulasi checkout','lisensi':'Lisensi saya','studio':'Studio kreator'})[parts[0]]||'Karya lokal, peluang baru'} — OTENTIK`;switch(parts[0]){case undefined:home();break;case 'katalog':catalog(params);break;case 'karya':detail(parts[1],params);break;case 'checkout':checkout(parts[1],params);break;case 'lisensi':parts[1]?license(parts[1]):licenses();break;case 'studio':studio();break;default:notFound();}window.scrollTo(0,0);if(focus)main.focus({preventScroll:true});}
document.querySelector('#cancel-reset').addEventListener('click',()=>document.querySelector('#reset-dialog').close());
document.querySelector('#confirm-reset').addEventListener('click',()=>{reset();document.querySelector('#reset-dialog').close();render();toast('Demo direset. Ringkasan kembali ke data contoh awal.');document.querySelector('#reset-demo')?.focus();});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
window.addEventListener('hashchange',()=>render());render(false);
// Motion is optional: a loading failure must never interrupt the core journey.
import('./motion.js').catch(()=>{});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_otentik_catalog',description:'Read demo artworks and simulated tier prices. Does not create licenses or transactions.',inputSchema:{type:'object',properties:{query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input!=='object'||(input.query!==undefined&&typeof input.query!=='string')||Object.keys(input).some(k=>k!=='query'))throw new Error('Expected optional string query.');const q=(input.query||'').toLowerCase();return works.filter(w=>(w.title+' '+w.category+' '+w.tags).toLowerCase().includes(q)).map(({id,title,category,prices})=>({id,title,category,prices,simulation:true}));}})).catch(()=>{});}catch{}}
